SELECT a.CSNAME AS `股票名称`, a.COMB_SYMBOL AS `股票代码`, c.F001D AS `财政周期结束日期`, c.F056N AS `财政年度`, c.F005V AS `货币`, ROUND(c.F032N * 100, 1) AS `净利润(万美元)`, c.F032N AS `净利润(百万美元)` FROM AMERICAN_STOCK_MAIN a JOIN VIEW_COM3103_CUM c ON a.FIU_ID = c.FIU_ID WHERE a.CSNAME LIKE '%英伟达%' AND c.F056N = 2025 AND c.F003V = 'FY' AND c.F032N IS NOT NULL ORDER BY c.F001D DESC LIMIT 1;
